import sys
import os

if hasattr(sys.stdout, 'reconfigure'):
    sys.stdout.reconfigure(encoding='utf-8')

from build_mahamanthan_sat_base import (
    create_base_presentation,
    add_title_slide,
    add_instructions_slide,
    add_interactive_mcq_pair,
    add_score_cutoff_slide,
    add_memory_key_slide,
    add_closing_branding_slide,
    finalize_and_save_sat_presentation
)

def build_sat_test(filename, test_num, qs_science, qs_sst, qs_math, memory_keys):
    prs = create_base_presentation()

    add_title_slide(
        prs,
        badge_text=f"NMMS SAT FULL EXAM SIMULATOR • TEST {test_num:02d}",
        main_title=f"सम्पूर्ण SAT महामंथन मॉक टेस्ट #{test_num:02d}",
        sub_desc="विज्ञान (35 अंक) + सामाजिक विज्ञान (35 अंक) + गणित (20 अंक) = कुल 90 अंक",
        topics_list=[
            "भाग 1: विज्ञान (35 प्रश्न) — भौतिकी, रसायन एवं जीव विज्ञान",
            "भाग 2: सामाजिक विज्ञान (35 प्रश्न) — इतिहास, भूगोल एवं नागरिक शास्त्र",
            "भाग 3: गणित (20 प्रश्न) — अंकगणित, बीजगणित, ज्यामिति एवं क्षेत्रमिति",
            "विगत 10 वर्षों के ऑल इंडिया NMMS पेपर्स पर आधारित शत-प्रतिशत प्रामाणिक प्रश्न",
            "2-स्लाइड इंटरैक्टिव पैटर्न (उत्तर पहले पूरी तरह छुपा रहेगा)"
        ]
    )

    add_instructions_slide(prs, f"SAT महामंथन टेस्ट #{test_num:02d}")

    for q_num, question, opts, corr, expl, tag in qs_science:
        add_interactive_mcq_pair(prs, q_num, question, opts, corr, expl, tag, subject_name="भाग 1: विज्ञान (Science)")

    for q_num, question, opts, corr, expl, tag in qs_sst:
        add_interactive_mcq_pair(prs, q_num, question, opts, corr, expl, tag, subject_name="भाग 2: सामाजिक विज्ञान (Social Science)")

    for q_num, question, opts, corr, expl, tag in qs_math:
        add_interactive_mcq_pair(prs, q_num, question, opts, corr, expl, tag, subject_name="भाग 3: गणित (Mathematics)")

    add_score_cutoff_slide(prs, f"SAT महामंथन टेस्ट #{test_num:02d}")
    add_memory_key_slide(prs, f"SAT महामंथन टेस्ट #{test_num:02d}", memory_keys)
    add_closing_branding_slide(prs, f"SAT MOCK TEST {test_num:02d}", f"SAT महामंथन टेस्ट #{test_num:02d}")

    finalize_and_save_sat_presentation(prs, filename)


